class MyCITAKarier(Component):
    display_name = "myCITA Karier"
    description = (
        "Eksplorasi karier myCITA: mencocokkan minat, skill, pengalaman, dan pendidikan pengguna dengan database profesi; "
        "menghasilkan 3 rekomendasi profesi beserta alasan, skill gap, jalur belajar dan biayanya, jenjang karier, rentang gaji "
        "per tahap (dengan sumber), serta jadwal pendapatan untuk simulasi finansial. Input JSON: user_id, minat[], skill[], "
        "pengalaman[{bidang, tahun}], pendidikan_terakhir, kota, opsional target_profesi dan penghasilan_sekarang. "
        "Semua angka dari database, bukan perkiraan AI."
    )
    icon = "briefcase"
    name = "MyCITAKarier"

    inputs = [
        MessageTextInput(
            name="input_json",
            display_name="Profil Karier (JSON)",
            info='Contoh {"user_id": "budi", "minat": ["angka", "komputer"], "skill": ["excel"], "pengalaman": [{"bidang": "gudang", "tahun": 9}]}',
            tool_mode=True,
        ),
        StrInput(name="db_path", display_name="Lokasi Database", value="", advanced=True,
                 info="Kosongkan untuk memakai ~/.mycita/mycita.db. Harus sama di semua komponen myCITA."),
    ]
    outputs = [Output(display_name="Hasil", name="hasil", method="eksplorasi_karier_mycita")]

    def eksplorasi_karier_mycita(self) -> Message:
        try:
            data = parse_input(self.input_json)
            uid = str(data.get("user_id") or "").strip().lower().replace(" ", "_")
            profil = baca_data(uid, "profil", self.db_path) if uid else None
            sebelumnya = (baca_data(uid, "karier", self.db_path) or {}).get("input") if uid else None
            dipakai = []
            if isinstance(sebelumnya, dict):
                for kunci in ("minat", "skill"):  # gabungkan: pengguna sering hanya menyebut sebagian
                    lama = _daftar(sebelumnya.get(kunci))
                    baru = _daftar(data.get(kunci))
                    nama = lambda x: _norm(x.get("nama") if isinstance(x, dict) else x)
                    tambahan = [x for x in lama if nama(x) not in {nama(y) for y in baru}]
                    if tambahan:
                        data[kunci] = list(baru) + tambahan; dipakai.append(kunci)
                for kunci in ("pengalaman", "pendidikan_terakhir", "kota", "status", "target_profesi"):
                    if not data.get(kunci) and sebelumnya.get(kunci):
                        data[kunci] = sebelumnya[kunci]; dipakai.append(kunci)
            hasil = analisis_karier(data, profil)
            if dipakai:
                hasil["memakai_data_tersimpan"] = dipakai
            payload = {"status": "ok", "user_id": uid or None,
                       "pesan": "Eksplorasi karier selesai: " + ", ".join(r["profesi"] for r in hasil["rekomendasi"]) + ".", **hasil,
                       "catatan_opsi": {
                           "jurusan": "Kecocokan jurusan dihitung dari minat, skill, dan kegiatan yang Anda isi; ini panduan awal dan bukan penentu lolos seleksi.",
                           "kampus_peringkat": "Peringkat kampus memakai QS World University Rankings dalam database myCITA dan bisa berubah tiap tahun; peringkat tinggi belum tentu paling cocok untuk jurusan Anda.",
                           "kampus_dekat": "Kampus dekat tempat tinggal dipilih dari kota yang Anda isi; cek jalur seleksi, daya tampung, dan biaya terbaru di situs kampus.",
                           "biaya": "Biaya per semester berupa rentang UKT atau BPP dari database myCITA; nominal akhir tergantung jalur masuk dan golongan UKT.",
                           "gaji": "Rentang gaji berasal dari data iklan lowongan dan laporan gaji (bukan survei resmi) dan berbeda per perusahaan dan kota; nilai tengah dipakai sebagai acuan.",
                           "kecocokan_karier": "Skor kecocokan karier dihitung dari minat, skill, pengalaman, dan pendidikan yang Anda isi; ini gambaran awal, bukan keputusan.",
                       },
                       "catatan_penutup": ("Kecocokan jurusan dihitung dari minat, skill, dan kegiatan yang Anda isi; ini panduan awal dan bukan penentu lolos seleksi."
                                           if hasil.get("mode_pelajar") else
                                           "Rentang gaji berasal dari data iklan lowongan dan laporan gaji (bukan survei resmi) dan berbeda per perusahaan dan kota; nilai tengah dipakai sebagai acuan."),
                       "disclaimer": "Rekomendasi adalah gambaran awal berdasarkan data yang kamu isi dan data referensi pasar. Keputusan tetap di tanganmu."}
            if uid:
                simpan_data(uid, "karier", {"input": data, "hasil": hasil}, self.db_path)
        except Exception as e:  # noqa: BLE001
            payload = galat(str(e))
        return hasil_message(self, payload)

