STOP_PUSTAKA = {"yang", "dan", "di", "ke", "dari", "untuk", "dengan", "atau", "apa", "berapa", "saja", "ada", "itu", "ini",
                "adalah", "dalam", "pada", "per", "the", "of", "a", "an", "is", "mana", "bagaimana", "gimana", "tolong",
