def _db_path(custom: str = "") -> str:
    env = os.environ.get("MYCITA_DB_PATH")
    p = Path((custom or env or str(Path.home() / ".mycita" / "mycita.db")).strip()).expanduser()
    p.parent.mkdir(parents=True, exist_ok=True)
    return str(p)


def _angka(s, ada_satuan):
    s = s.strip(".,")
    if ada_satuan:
        if re.fullmatch(r"\d{1,3}(\.\d{3})+", s):
            return float(s.replace(".", "")), 0
        if "," in s:
            a, b = s.split(",", 1)
            return float(a.replace(".", "") + "." + b), len(b)
        if "." in s:
            a, b = s.split(".", 1)
            return float(a + "." + b), len(b)
        return float(s), 0
    if re.fullmatch(r"\d{1,3}(\.\d{3})+", s):
        return float(s.replace(".", "")), 0
    if re.fullmatch(r"\d{1,3}(,\d{3})+", s):
        return float(s.replace(",", "")), 0
    if "," in s:
        a, b = s.split(",", 1)
        return float(a + "." + b), len(b)
    if "." in s:
        a, b = s.split(".", 1)
        return float(a + "." + b), len(b)
    return float(s), 0


def ekstrak(teks):
    """Daftar (label, nilai, toleransi, tipe). tipe: rp | bln | pct | lain."""
    out, t = [], KATA_NASIHAT_KECIL.sub(" ", teks)

    def ambil(pat, fn):
        nonlocal t
        for m in list(re.finditer(pat, t, re.I)):
            r = fn(m)
            if r:
                out.append(r)
        t = re.sub(pat, " ", t, flags=re.I)

    def rp(m):
        sat = (m.group("sat") or "").lower()
        v, d = _angka(m.group("n"), bool(sat))
        mult = SATUAN.get(sat, 1)
        return (m.group(0).strip(), v * mult, 0.5 * 10 ** (-d) * mult if (sat or d) else 0.5, "rp")

    def dur(m):
        th = int(m.group("th") or 0)
        bl, d = _angka(m.group("bl") or "0", False)
        return (m.group(0).strip(), th * 12 + bl, 0.5 * 10 ** (-d), "bln")

    def pc(m):
        v, d = _angka(m.group(1), False)
        return (m.group(0).strip(), v, 0.5 * 10 ** (-d), "pct")

    ambil(r"(?:Rp\.?\s*)?(?P<n>\d[\d.,]*)\s*(?P<sat>miliar|milyar|juta|jt|ribu)\b", rp)
    ambil(r"Rp\.?\s*(?P<n>\d[\d.,]*)(?P<sat>)", rp)
    ambil(r"(?:(?P<th>\d+)\s*tahun)?\s*(?:(?P<bl>\d+(?:[.,]\d+)?)\s*bulan)", dur)
    ambil(r"(?P<th>\d+)\s*tahun(?P<bl>)", dur)
    ambil(r"(\d+(?:[.,]\d+)?)\s*%", pc)
    t = re.sub(r"(?m)^\s*\d+[.)]\s", " ", t)
    t = re.sub(r"\b20[0-9]{2}\b", " ", t)
    for m in re.finditer(r"(?<![\w.])\d+(?:[.,]\d+)?(?![\w])", t):
        v, d = _angka(m.group(0), False)
        if v == int(v) and v <= 10 and d == 0:
            continue
        out.append((m.group(0), v, 0.5 * 10 ** (-d), "lain"))
    return out


def kumpulkan(obj, T=None, kunci=""):
    if T is None:
        T = {"rp": set(), "bln": set(), "pct": set(), "lain": set()}
    if isinstance(obj, bool) or obj is None:
        return T
    if isinstance(obj, (int, float)):
        v, k = float(obj), kunci.lower()
        if "bulan" in k or "bln" in k:
            T["bln"].add(v)
        elif "persen" in k or "rate" in k or "pct" in k:
            T["pct"].add(v)
        elif abs(v) >= 1000:
            T["rp"].add(v)
        T["lain"].add(v)
    elif isinstance(obj, str):
        for _, v, _, tp in ekstrak(obj):
            T[tp].add(float(v))
            T["lain"].add(float(v))
    elif isinstance(obj, dict):
        for k, v in obj.items():
            kumpulkan(v, T, str(k))
    elif isinstance(obj, list):
        for v in obj:
            kumpulkan(v, T, kunci)
    return T


def _cocok(T, label, v, tol, tp):
    def ada(daftar, x, tl):
        i = bisect.bisect_left(daftar, x - tl - 1e-9)
        return i < len(daftar) and daftar[i] <= x + tl + 1e-9

    if tp == "rp":
        pool = [T["rp"]]
    elif tp == "bln":
        pool = [T["bln"]]
    elif tp == "pct":
        pool = [T["pct"], T["lain"]]
    else:
        pool = [T["lain"]]
    if any(ada(p, v, tol) for p in pool):
        return True
    if tp == "pct" and ada(T["lain"], v / 100, tol / 100):
        return True
    return False



def _durasi_dalam(obj):
    """Semua durasi (bulan) di dalam sub-pohon: dari teks 'X tahun Y bulan' dan angka pada kunci ber-'bulan'."""
    hasil = set()
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, (int, float)) and not isinstance(v, bool) and ("bulan" in str(k).lower()):
                hasil.add(float(v))
            else:
                hasil |= _durasi_dalam(v)
    elif isinstance(obj, list):
        for v in obj:
            hasil |= _durasi_dalam(v)
    elif isinstance(obj, str):
        for _, v, _, tp in ekstrak(obj):
            if tp == "bln":
                hasil.add(float(v))
    return hasil


def _nama_target(obj, names):
    if isinstance(obj, dict):
        if isinstance(obj.get("nama"), str) and ("opsi_a_menabung" in obj or "kategori" in obj):
            names.add(obj["nama"].lower())
        tg = obj.get("target")
        if isinstance(tg, dict) and tg and all(isinstance(x, (str, type(None))) for x in tg.values()):
            names.update(str(n).lower() for n in tg)
        for v in obj.values():
            _nama_target(v, names)
    elif isinstance(obj, list):
        for v in obj:
            _nama_target(v, names)


def _isi_peta(obj, names, D, S):
    """D[nama_target] = durasi sah untuk target itu; S = nilai 'sisa' per bulan yang sah."""
    if isinstance(obj, dict):
        if isinstance(obj.get("nama"), str) and ("opsi_a_menabung" in obj or "kategori" in obj):
            D.setdefault(obj["nama"].lower(), set()).update(_durasi_dalam(obj))
        tg = obj.get("target")
        if isinstance(tg, dict) and tg and all(isinstance(x, (str, type(None))) for x in tg.values()):
            for n, w in tg.items():
                D.setdefault(str(n).lower(), set()).update(_durasi_dalam(w))
        for k, v in obj.items():
            if isinstance(v, (int, float)) and not isinstance(v, bool) and str(k).lower() in ("sisa", "kapasitas_menabung", "disposable_income"):
                S.add(float(v))
            _isi_peta(v, names, D, S)
    elif isinstance(obj, list):
        for v in obj:
            _isi_peta(v, names, D, S)
    elif isinstance(obj, str):
        for m in re.finditer(r"sisa[^\d;]{0,40}(Rp\.?\s*\d[\d.]*(?:,\d+)?\s*(?:juta|jt|ribu)?)", obj, re.I):
            for _, v, _, tp in ekstrak(m.group(1)):
                S.add(float(v))
        for klausa in re.split(r"[;|]", obj):
            ada = [n for n in names if re.search(r"\b" + re.escape(n) + r"\b", klausa.lower())]
            if len(ada) == 1:
                D.setdefault(ada[0], set()).update(_durasi_dalam(klausa))


def _periksa_klausa(klausa, names, D, S, T):
    """Daftar angka yang tidak cocok pada satu klausa, dengan pengikatan konteks."""
    buruk = []
    ada = [n for n in names if re.search(r"\b" + re.escape(n) + r"\b", klausa.lower())]
    sah_target = set()
    for n in ada:
        sah_target |= D.get(n, set())
    sisa_ctx = re.search(r"\bsisa\b", klausa, re.I) is not None
    for lab, v, tol, tp in ekstrak(klausa):
        if not _cocok(T, lab, v, tol, tp):
            buruk.append(lab)
            continue
        if tp == "bln" and ada and any(D.get(n) for n in ada):
            if not any(abs(v - x) <= tol + 1e-9 for x in sah_target):
                buruk.append(lab)
        elif tp == "rp" and sisa_ctx and S:
            tepat_setelah_sisa = re.search(r"sisa[^\d;]{0,40}" + re.escape(lab), klausa, re.I)
            if tepat_setelah_sisa and not any(abs(v - x) <= tol + 1e-9 for x in S):
                buruk.append(lab)
    return buruk



ATURAN_KOLOM = [  # (kata di judul kolom, potongan nama kunci di keluaran mesin)
    ("tambahan laba", ("tambahan_laba",)),
    ("sisa", ("sisa", "disposable_income")),
    ("budget", ("budget_maksimal", "harga_maksimal")),
    ("harga sekarang", ("harga_saat_ini",)),
    ("penghasilan", ("pendapatan", "penghasilan")),
    ("pengeluaran", ("pengeluaran",)),
]


def _nilai_per_kunci(obj, anc=(), hasil=None):
    """Kumpulkan angka bulat dengan daftar nama kunci leluhurnya, untuk pemeriksaan per kolom tabel."""
    if hasil is None:
        hasil = []
    if isinstance(obj, dict):
        for k, v in obj.items():
            _nilai_per_kunci(v, anc + (str(k).lower(),), hasil)
    elif isinstance(obj, list):
        for v in obj:
            _nilai_per_kunci(v, anc, hasil)
    elif isinstance(obj, (int, float)) and not isinstance(obj, bool):
        hasil.append((anc, float(obj)))
    return hasil


def _peta_kolom(payloads):
    semua = []
    for p in payloads:
        _nilai_per_kunci(p, (), semua)
    peta = {}
    for judul, potongan in ATURAN_KOLOM:
        peta[judul] = {v for anc, v in semua if any(any(pt in a for pt in potongan) for a in anc)}
    return peta


def _periksa_kolom(baris, header, peta):
    """Untuk baris tabel: setiap nilai Rupiah harus ada di himpunan kolomnya (bila kolom dikenali)."""
    sel = [c.strip() for c in baris.strip().strip("|").split("|")]
    buruk = []
    for j, c in enumerate(sel):
        if j >= len(header) or not c:
            continue
        h = header[j].lower()
        aturan = next((jd for jd, _ in ATURAN_KOLOM if jd in h), None)
        if not aturan or not peta.get(aturan):
            continue
        for lab, v, tol, tp in ekstrak(c):
            if tp == "rp" and not any(abs(v - x) <= tol + 1e-9 for x in peta[aturan]):
                buruk.append(lab)
    return buruk



def _rp(x):
    n = int(round(float(x)))
    return ("-" if n < 0 else "") + "Rp" + f"{abs(n):,}".replace(",", ".")


def _tabel_usaha(pb):
    """Tabel perbandingan usaha berjalan yang seluruhnya diambil dari keluaran mesin."""
    sk = pb.get("skenario") or {}
    if not sk:
        return None
    baris = ["| Skenario | Tambahan laba/bulan | Sisa/bulan | Waktu tercapai | Budget maksimal tepat tenggat |", "|---|---|---|---|---|"]
    for nama, v in sk.items():
        label = "Semua usaha" if nama == "semua_usaha" else nama.replace("_saja", "").capitalize() + " saja"
        waktu = "; ".join(f"{n} {w}" for n, w in (v.get("target") or {}).items()) or "-"
        bud = "; ".join(f"{n} {_rp(b)}" for n, b in (v.get("budget_maksimal_agar_tepat_tenggat") or {}).items()) or "-"
        if len(v.get("target") or {}) <= 1:
            waktu = "; ".join(str(w) for w in (v.get("target") or {}).values()) or "-"
            bud = "; ".join(_rp(b) for b in (v.get("budget_maksimal_agar_tepat_tenggat") or {}).values()) or "-"
        baris.append(f"| {label} | {_rp(v.get('tambahan_laba_bulanan', 0))} | {_rp(v.get('sisa', 0))} | {waktu} | {bud} |")
    return baris


def _teks(x):
    return getattr(x, "text", x) if x is not None else ""


class MyCITAPenjagaFidelitas(Component):
    display_name = "myCITA Penjaga Fidelitas"
    description = ("Memeriksa semua angka di jawaban AI terhadap keluaran alat (mesin Python) pada percakapan yang sama. "
                   "Baris dengan angka yang tidak cocok dihapus dan diganti blok angka terverifikasi dari mesin.")
    icon = "shield-check"
    name = "MyCITAPenjagaFidelitas"

    inputs = [
        MessageTextInput(name="jawaban", display_name="Jawaban AI (dari Agent)", info="Sambungkan dari output Agent."),
        MessageTextInput(name="pesan_pengguna", display_name="Pesan Pengguna (dari Chat Input)",
                         info='Dipakai membaca user_id, mis. "user budi: ...".'),
        StrInput(name="db_path", display_name="Lokasi Database", value="", advanced=True,
                 info="Kosongkan untuk ~/.mycita/mycita.db. Harus sama dengan komponen myCITA lain."),
        StrInput(name="jendela_detik", display_name="Jendela Waktu (detik)", value="900", advanced=True,
                 info="Hanya keluaran alat dalam rentang ini yang dipakai sebagai pembanding."),
        StrInput(name="catatan_terlihat", display_name="Catatan Terlihat (ya/tidak)", value="tidak", advanced=True,
                 info="Jika 'ya', catatan koreksi ditulis di bawah jawaban. Jika 'tidak', rincian koreksi hanya ada di status node."),
        StrInput(name="mode", display_name="Mode", value="hapus", advanced=True,
                 info='"hapus" = baris tidak cocok dihapus; "tandai" = hanya diberi catatan.'),
    ]
    outputs = [Output(display_name="Jawaban Terverifikasi", name="hasil", method="jaga")]

    def _jejak(self, uid):
        jendela = float(self.jendela_detik or 900)
        conn = sqlite3.connect(_db_path(self.db_path))
        try:
            conn.execute("CREATE TABLE IF NOT EXISTS mycita_jejak (id INTEGER PRIMARY KEY AUTOINCREMENT, user_id TEXT, tool TEXT, ts REAL, payload TEXT)")
            rows = conn.execute("SELECT user_id, tool, payload FROM mycita_jejak WHERE ts >= ? ORDER BY ts", (time.time() - jendela,)).fetchall()
        finally:
            conn.close()
        out = []
        for u, tool, p in rows:
            if uid and u and u != uid:
                continue
            try:
                out.append((tool, json.loads(p)))
            except Exception:  # noqa: BLE001
                pass
        return out

    def jaga(self) -> Message:
        jawaban = str(_teks(self.jawaban) or "")
        pesan = str(_teks(self.pesan_pengguna) or "")
        try:
            kandidat = []
            for mm in re.finditer(r"user(?:[_ ]id)?\s*[:=]?\s*(?=([A-Za-z0-9_\-]+))", pesan, re.I):
                c_ = mm.group(1).lower()
                if c_ not in kandidat and c_ not in ("user", "id"):
                    kandidat.append(c_)
            uid, jejak = "", []
            for c_ in kandidat:  # pakai kandidat pertama yang punya jejak alat (tahan terhadap teks tempelan "User")
                jejak = self._jejak(c_)
                if jejak:
                    uid = c_
                    break
            if not jejak or not re.search(r"\d", jawaban):
                self.status = "Tidak ada keluaran alat untuk dicocokkan; jawaban diteruskan."
                return Message(text=jawaban)
            T = kumpulkan([p for _, p in jejak])
            # angka yang disebut pengguna sendiri sah di kalimat biasa, tetapi tidak di baris tabel
            # atau kalimat 'tambahan laba' (di sana angka harus berasal dari keluaran mesin).
            Tu = {k: set(v) for k, v in T.items()}
            for _, v, _, tp in ekstrak(pesan):
                Tu[tp].add(float(v))
                Tu["lain"].add(float(v))
            for k in T:
                T[k] = sorted(T[k])
                Tu[k] = sorted(Tu[k])
            names, D, S = set(), {}, set()
            _nama_target([p for _, p in jejak], names)
            _isi_peta([p for _, p in jejak], names, D, S)
            peta = _peta_kolom([p for _, p in jejak])
            header = []
            baris_baru, dihapus = [], []
            for baris in jawaban.split("\n"):
                buruk = []
                st = baris.strip()
                if st.startswith("|"):
                    if re.match(r"^\|[\s:\-|]+\|?$", st):
                        pass
                    elif not header:
                        header = [c.strip() for c in st.strip("|").split("|")]
                    else:
                        buruk += _periksa_kolom(baris, header, peta)
                else:
                    header = []
                for klausa in re.split(r"[;|]|,\s|\s[—–]\s|\)\s*:", baris):
                    ketat = baris.lstrip().startswith("|") or "tambahan laba" in baris.lower() or "modal" in baris.lower()
                    buruk += _periksa_klausa(klausa, names, D, S, T if ketat else Tu)
                if re.search(r"sesuai\s+(yang\s+)?(kamu|anda|yang\s+anda|yang\s+kamu)\s+sebut", baris, re.I):
                    buruk.append("klaim 'sesuai yang disebutkan' tidak bisa diverifikasi")
                if buruk and self.mode != "tandai":
                    dihapus.append((baris, buruk))
                    continue
                baris_baru.append(baris + (f"  ⚠ angka belum terverifikasi: {', '.join(buruk)}" if buruk else ""))
            tabel_koreksi = None
            if any(b.lstrip().startswith("|") for b, _ in dihapus):
                for tool, p in jejak:
                    if tool == "MyCITAAnalisis" and p.get("perbandingan_usaha_berjalan"):
                        tabel_koreksi = _tabel_usaha(p["perbandingan_usaha_berjalan"]) or tabel_koreksi
            if tabel_koreksi:
                sisa_baris, posisi = [], None
                for b in baris_baru:
                    if b.lstrip().startswith("|"):
                        if posisi is None:
                            posisi = len(sisa_baris)
                        continue
                    sisa_baris.append(b)
                if posisi is not None:
                    sisa_baris[posisi:posisi] = tabel_koreksi
                else:
                    sisa_baris = tabel_koreksi + sisa_baris
                baris_baru = sisa_baris
                dihapus_lain = [d for d in dihapus if not d[0].lstrip().startswith("|")]
            else:
                dihapus_lain = dihapus
            hasil = "\n".join(baris_baru).rstrip()
            # Pengaman tampilan: jika jawaban membahas rentang gaji tetapi tabel gaji dari mesin tidak disalin, sisipkan.
            try:
                if "rentang gaji" in hasil.lower() and "| Tahap |" not in hasil:
                    kandidat_tabel = None
                    for tool, p in jejak:
                        for rk in (p.get("rekomendasi") or []):
                            if isinstance(rk, dict) and rk.get("tampilan_gaji_markdown"):
                                nm = str(rk.get("profesi", "")).lower()
                                gabungan = (hasil + " " + pesan).lower()
                                kata = [w for w in re.split(r"\W+", nm) if len(w) >= 4]
                                if nm and kandidat_tabel is None and (nm in gabungan or (kata and all(w in gabungan for w in kata[:1]))):
                                    kandidat_tabel = rk["tampilan_gaji_markdown"]
                    if kandidat_tabel:
                        hasil = kandidat_tabel.strip() + "\n\n" + hasil
            except Exception:  # noqa: BLE001
                pass
            catatan = []
            if tabel_koreksi:
                catatan.append("tabel perbandingan dikoreksi otomatis dari hasil mesin")
            if dihapus_lain:
                catatan.append(f"{len(dihapus_lain)} baris dihapus karena angkanya tidak cocok dengan hasil mesin")
            if catatan and str(getattr(self, "catatan_terlihat", "tidak")).strip().lower() == "ya":
                hasil += "\n\nCatatan: " + "; ".join(catatan) + " (angka dijaga agar selalu sama dengan perhitungan Python)."
            self.status = (f"{len(dihapus)} baris dihapus" + (" (tabel dikoreksi)" if tabel_koreksi else "") if dihapus else ("Ada angka ditandai." if "⚠ angka belum" in hasil else "Semua angka cocok."))
            if dihapus:
                self.status += " | dihapus: " + " || ".join(str(d[0]).strip()[:120] for d in dihapus[:4])
            return Message(text=hasil)
        except Exception as e:  # noqa: BLE001
            self.status = f"Penjaga gagal ({e}); jawaban diteruskan."
            return Message(text=jawaban)
